const ip = $input.item.json?.headers?.['x-forwarded-for'] || $input.item.headers?.['x-forwarded-for'] || 'localhost';
const today = new Date().toISOString().split('T')[0];
const staticData = $getWorkflowStaticData('global');
staticData.quota = staticData.quota || {};
staticData.quota[today] = staticData.quota[today] || { globalLimit: 0, ips: {} };
let ipData = staticData.quota[today].ips[ip] || 0;
let isAllowed = true;
let reason = "";


let incomingData = $input.item.json.body?.data || $input.item.json.data || $input.item.json;
return { isAllowed, reason, data: incomingData };

const prefs = $input.item.json.data.preferences || {};
const ingredients = JSON.stringify($input.item.json.data.ingredients || []);

const prompt = `Create exactly 3 recipes. 
Cuisine: ${prefs.cuisineStyle}
Diet: ${prefs.dietType}
Portions: ${prefs.portions}
Use ingredients: ${ingredients}. 

RULES:
1. Use at least 70% of the ingredients provided.
2. You can add a MAXIMUM of 3 extra basic ingredients.
3. Split the cooking instructions clearly between ${prefs.personsCooking || 1} chef(s).
4. Make the cooking instructions (text in steps) VERY DETAILED, descriptive, and at least 2-3 sentences long per step. Explain exactly HOW to cook it.

Output exactly this JSON structure: 
[ { "title": "Name", "time": "20min", "portions": ${prefs.portions}, "chefsCount": ${prefs.personsCooking || 1}, "likes": 0, "tags": ["Tag1"], "nutrition": { "energy": "500 kcal", "protein": "20g", "fat": "15g", "carbs": "40g" }, "myIngredients": [ { "amount": "100g", "name": "Pasta" } ], "extraIngredients": [ { "amount": "1 tbsp", "name": "Oil" } ], "steps": [ { "num": 1, "title": "Detailed Step Title", "chefId": 1, "text": "Detailed multi-sentence instruction goes here..." } ] } ]`;

const groqBody = {
  model: "llama-3.3-70b-versatile",
  temperature: 0.7,
  messages: [
    {
      role: "system",
      content: "You are a professional Michelin-star chef. Reply ONLY with a raw JSON array of exactly 3 recipes. NO MARKDOWN, no conversational text."
    },
    {
      role: "user",
      content: prompt
    }
  ]
};

return { groqBody: groqBody };

let rawContent = $input.item.json.choices[0].message.content;


rawContent = rawContent.replace(/```json/g, '').replace(/```/g, '').trim();

let recipesList = JSON.parse(rawContent);

return {
  success: true,
  recipes: recipesList
};
